      'Algenib, Betelgeuse, Sirius, Polaris—',
      'I was small beneath it all, but the whole sky felt like ours.',
      '[Verse 2]',
      'Algenib—blue beat, deep-space drum,',
      'Three-point-six-hour rhythm saying, “Come, child, come.”',
      'Pressure waves race while the gravity rolls,',
      'A pulsing blue jewel in the Pegasus folds.',
      'Blue-white blaze with a heartbeat hidden,',
      'Cosmic code in a cadence unwritten.',
      'I couldn’t spell pulsation or chart its flight,',
      'But I felt that distant drummer drum through night.',
      '[Hook]',
      'Beat, beat—blue flame, bright.',
      'Beat, beat—through the night.',
      'Far, far—still you came.',
      'Algenib—I learned your name.',
      '[Verse 3]',
      'Betelgeuse burns on Orion’s broad shoulder,',
      'Red as a ruby, enormous and older.',
      'A supergiant swelling, a furnace unfurled—',
      'Placed where our Sun is, it could swallow inner worlds.',
      'Then the giant dimmed and the whole Earth stared;',
      'It hurled out matter and its brilliance was impaired.',
      'Cooling gas formed dust, making red fire hide—',
      'Even wounded wonders still illuminate the sky.',
      '[Hook]',
      'Burn, Betelgeuse, burn—red gold, red glow.',
