      'Dim, then return; let the darkness testify:',
      'Even wounded wonders still illuminate the sky.',
      '[Verse 4]',
      'Sirius—serious shimmer, sharp silver flame,',
      'Brightest star at nighttime, Dog Star by name.',
      'Eight-point-six years for its light to arrive—',
      'Every glance at Sirius sees an earlier sky.',
      'One blaze is two in a beautiful spin:',
      'Sirius A with a secret companion within.',
      'Sirius B, Earth-small, nearly Sun-heavy,',
      'A white-dwarf diamond, collapsed and steady.',
      'Ten thousand times fainter beneath all that glare,',
      'A hidden little heavyweight quietly there.',
      'The brightest may never be burning alone,',
      'And the smallest-looking light may be denser than stone.',
      '[Verse 5]',
      'Polaris isn’t brightest—it is faithful in the frame,',
      'A northern-pointing promise with a navigator’s name.',
      'Not one lonely lantern but a family of three,',
      'A Cepheid softly breathing in celestial harmony.',
      'Sailors found salvation in its steady-seeming role,',
      'A silver signal sitting near the northern pole.',
      'But Earth spins and sways like a slow, dreaming top,',
      'So even North is borrowed; even guide stars swap.',
      'Thuban held the title; Vega waits beyond,',
      'The sky keeps rearranging what we thought would carry on.',
      'Still Polaris keeps pointing while our brief years pass,',
      'A pin through the heavens, a compass through the black.',
